const artFormsData=[{id:"madhubani",name:"Madhubani Painting",region:"Bihar",category:"madhubani",desc:"Folk art from the Mithila region, known for intricate geometric and floral patterns.",img:"https://placehold.co/400x300/e11d48/fff",link:"../madhubani-painting-explorer/index.html"},{id:"warli",name:"Warli Art",region:"Maharashtra",category:"warli",desc:"Tribal art form using basic geometric shapes to depict daily life and nature.",img:"https://placehold.co/400x300/78350f/fff",link:"../warli-art-explorer/index.html"},{id:"pattachitra",name:"Pattachitra Art",region:"Odisha",category:"pattachitra",desc:"Scroll painting tradition deeply rooted in mythological and religious themes.",img:"https://placehold.co/400x300/b45309/fff",link:"../pattachitra-art-explorer/index.html"},{id:"kalamkari",name:"Kalamkari Art",region:"Andhra Pradesh",category:"kalamkari",desc:"Hand-painted or block-printed cotton textile art depicting epics and folklore.",img:"https://placehold.co/400x300/065f46/fff",link:"../kalamkari-art-explorer/index.html"},{id:"tanchoi",name:"Tanchoi Weaving",region:"Varanasi",category:"other",desc:"Intricate brocade weaving technique blending Indian and Chinese traditions.",img:"https://placehold.co/400x300/4c1d95/fff"},{id:"phad",name:"Phad Painting",region:"Rajasthan",category:"other",desc:"Traditional scroll painting depicting folk deities like Pabuji and Devnarayan.",img:"https://placehold.co/400x300/be123c/fff"},{id:"miniature",name:"Rajput Miniature",region:"Rajasthan",category:"other",desc:"Highly detailed, small-scale paintings often illustrating royal courts and ragas.",img:"https://placehold.co/400x300/0369a1/fff"},{id:"thangka",name:"Thangka Painting",region:"Himalayas",category:"other",desc:"Sacred Tibetan Buddhist scroll paintings depicting deities and mandalas.",img:"https://placehold.co/400x300/1e3a8a/d4af37",link:"../thangka-painting-explorer/index.html"},{id:"gond",name:"Gond Art",region:"Madhya Pradesh",category:"other",desc:"Tribal art characterized by vibrant colors and dot/line patterns.",img:"https://placehold.co/400x300/15803d/fff"},{id:"chittara",name:"Chittara Painting",region:"Karnataka",category:"other",desc:"Traditional geometric folk art from the Devaragudda village.",img:"https://placehold.co/400x300/8B4513/fff",link:"../chittara-art-explorer/index.html"},{id:"lacquerware",name:"Indian Lacquerware",region:"Karnataka, Andhra Pradesh & Rajasthan",category:"other",desc:"Lac-turned wood craft behind Channapatna toys, Etikoppaka toys, Nirmal figures, and Jaipur lac bangles.",img:"https://placehold.co/400x300/7c2d12/f59e0b",link:"../lacquerware-explorer/index.html"}];let observer,currentCategory="all",searchTerm="";function init(){renderFeatured(),renderGallery(),attachEventListeners(),setupThemeToggle(),setupScrollAnimations()}function renderFeatured(){const e=document.getElementById("featured-grid"),a=artFormsData.filter(e=>["madhubani","warli","pattachitra","kalamkari"].includes(e.category));e.innerHTML=a.map(e=>`\n        <div class="featured-card animate-on-scroll">\n            <div class="featured-img" style="background-image: url('${e.img}')">\n                <span class="featured-badge">${e.region}</span>\n            </div>\n            <div class="featured-content">\n                <h3>${e.name}</h3>\n                <p>${e.desc}</p>\n                <a href="${e.link}" class="btn-explore" aria-label="Explore ${e.name}">Explore Gallery &rarr;</a>\n            </div>\n        </div>\n    `).join(""),document.querySelectorAll(".featured-card").forEach(e=>observer.observe(e))}function renderGallery(){const e=document.getElementById("art-grid"),a=artFormsData.filter(e=>{const a="all"===currentCategory||e.category===currentCategory,t=e.name.toLowerCase().includes(searchTerm.toLowerCase())||e.region.toLowerCase().includes(searchTerm.toLowerCase());return a&&t});0!==a.length?(e.innerHTML=a.map(e=>`\n        <div class="art-card animate-on-scroll" role="listitem" tabindex="0" ${e.link?`onclick="window.location.href='${e.link}'"`:""}>\n            <div class="art-card-img" style="background-image: url('${e.img}')"></div>\n            <div class="art-card-content">\n                <h4>${e.name}</h4>\n                <p>${e.desc}</p>\n                <div class="art-card-tags">\n                    <span class="tag">${e.region}</span>\n                    <span class="tag">${e.category}</span>\n                </div>\n            </div>\n        </div>\n    `).join(""),document.querySelectorAll(".art-card").forEach(e=>observer.observe(e))):e.innerHTML='<p style="grid-column: 1/-1; text-align: center; color: var(--text-secondary);">No art forms found matching your criteria.</p>'}function attachEventListeners(){document.querySelectorAll(".filter-btn").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".filter-btn").forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),e.classList.add("active"),e.setAttribute("aria-selected","true"),currentCategory=e.dataset.category,renderGallery()})});const e=document.getElementById("art-search");e&&e.addEventListener("input",debounce(e=>{searchTerm=e.target.value,renderGallery()},300))}function setupThemeToggle(){const e=document.getElementById("theme-toggle");e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const a=document.body.classList.contains("light-theme");localStorage.setItem("theme",a?"light":"dark"),e.textContent=a?"☀️":"🌙"}),"light"===localStorage.getItem("theme")&&(document.body.classList.add("light-theme"),e.textContent="☀️")}function setupScrollAnimations(){observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1}),document.querySelectorAll(".animate-on-scroll").forEach(e=>observer.observe(e))}function debounce(e,a){let t;return function(...r){clearTimeout(t),t=setTimeout(()=>e.apply(this,r),a)}}document.addEventListener("DOMContentLoaded",init);